{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Measure BB Annual General Adjustment 5% cap","requirement":"The Annual General Adjustment by which a landlord of a fully covered unit may raise rent may not exceed 5%, even if the Rent Ordinance formula would allow a larger increase.","key_value":"5% maximum AGA per year","coverage_conditions":"Fully covered rental units in Berkeley; the Rent Board sets the AGA annually under a CPI-based formula.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Fully covered units"},"exemptions":"Landlords with banked (unused) AGAs from previous years may still raise rent above 5% to reach the rent ceiling.","penalty":null,"effective_date":null,"citation":"Measure BB (Berkeley Rent Ordinance)","quoted_span":"The maximum AGA is 5%. This means that, if the formula in the Rent Ordinance results in an AGA that is greater than 5%, the AGA approved by the Board for that year can be no more than 5%.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Measure BB coverage of government-owned or -subsidized units","requirement":"Landlords of government-owned or -subsidized rental units must register them with the Rent Board as fully or partially covered and pay an annual registration fee; fully covered units have a rent ceiling.","key_value":null,"coverage_conditions":"Government-owned or -subsidized units, including Housing Choice Voucher (Section 8), Shelter Plus Care, VASH, LIHTC, HOME and others; full or partial coverage depends on unit type.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Government-owned or subsidized rental units"},"exemptions":"Units where Federal law, State law or administrative regulation prohibits rent control are only partially covered, e.g. Section 202, Section 811, and project-based Section 8 in projects with HUD-held or -insured mortgages.","penalty":null,"effective_date":null,"citation":"Measure BB (Berkeley Rent Ordinance)","quoted_span":"Landlords of government-owned or -subsidized units must register them with the Rent Board as either fully or partially covered, and pay an annual registration fee.","interaction":"Depends on whether Federal law, State law, or administrative regulation exempts the unit from the rent control provisions of Berkeley’s Rent Ordinance.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Measure BB change to shared kitchen or bath exemption","requirement":"A unit where the tenant shares a kitchen or bath with the landlord is exempt from the Rent Ordinance only if the landlord lived in a unit on the same property at the start of the tenancy.","key_value":null,"coverage_conditions":"Rental units in which the tenant shares kitchen or bath facilities with the landlord.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Units where tenant shares kitchen or bath with landlord"},"exemptions":"Exempt only where the landlord lived in a unit on the same property at the start of the tenancy.","penalty":null,"effective_date":null,"citation":"Measure BB (Berkeley Rent Ordinance)","quoted_span":"Where the tenant shares a kitchen or bath facilities with the landlord, the unit will be exempt from the Rent Ordinance only if the landlord lived in a unit on the same property at the start of the tenancy.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Measure BB limits capital improvement rent increase petitions to completed work","requirement":"A landlord may petition for a rent increase only for completed capital improvements and may no longer obtain preliminary authorization of increases for planned capital improvements.","key_value":null,"coverage_conditions":"All rental units covered by the Berkeley Rent Ordinance.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All covered rental units"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Measure BB (Berkeley Rent Ordinance)","quoted_span":"Landlords can only file a petition for rent increases for completed capital improvements (they can no longer petition to have rent increases preliminarily authorized for planned capital improvements).","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Measure BB minimum rental debt for nonpayment eviction","requirement":"A landlord may not evict a tenant for nonpayment of rent unless the rental debt equals or exceeds one month of HUD Fair Market Rent for a unit of equivalent size for the fiscal year in which rent is demanded.","key_value":"1 month FMR (Oakland-Fremont, CA HUD Metro FMR)","coverage_conditions":"Tenants in units fully or partially covered by the Berkeley Rent Ordinance.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Fully or partially covered units"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Measure BB (Berkeley Rent Ordinance)","quoted_span":"For a landlord to evict a tenant for nonpayment of rent, the tenant must owe an amount of rental debt equal to or greater than one month of the Fair Market Rent (FMR) value for a unit of equivalent size in the metro area Oakland-Fremont, CA HUD Metro FMR as determined by the US Department of Housing and Urban Development for the fiscal year in which the rent is demanded.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Measure BB eliminates failure to sign a substantially similar lease as just cause","requirement":"A landlord may not evict a tenant for refusing to sign a substantially similar lease when a fixed-term lease expires.","key_value":null,"coverage_conditions":"Tenants in units fully or partially covered by the Berkeley Rent Ordinance.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Fully or partially covered units"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Measure BB (Berkeley Rent Ordinance)","quoted_span":"A landlord cannot evict a tenant for failing to sign a substantially similar lease upon expiration of a fixed-term lease.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Measure BB requirements for lease-breach evictions","requirement":"To evict for breach of a material lease term, the term must be mutually agreed, the breach must cause substantial actual damage to the landlord, the tenant's behavior must be unreasonable, and the notice must describe the term, violation and harm in detail.","key_value":null,"coverage_conditions":"Tenants in units fully or partially covered by the Berkeley Rent Ordinance.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Fully or partially covered units"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Measure BB (Berkeley Rent Ordinance)","quoted_span":"Material lease terms only include mutually agreed upon lease terms. The alleged violation must cause substantial, actual damage to the landlord. The landlord must demonstrate that the tenant’s behavior was unreasonable.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Measure BB eviction notice content and Rent Board filing deadline","requirement":"Any notice terminating a tenancy must state that Rent Board advice is available with its phone number and website, and the landlord must file the notice, notice to quit, and summons and complaint with the Rent Board within three business days of service.","key_value":"3 business days to file with Rent Board","coverage_conditions":"Tenants in units fully or partially covered by the Berkeley Rent Ordinance.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Fully or partially covered units"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Measure BB (Berkeley Rent Ordinance)","quoted_span":"The landlord must file with the Rent Board a copy of any notice to terminate a tenancy, notice to quit, and summons and complaint no later than three business days after the tenant was served with the document.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Measure BB mandatory annual adjustment of owner move-in relocation assistance","requirement":"The Rent Board must make inflationary adjustments each year to the relocation assistance amounts paid in owner move-in evictions.","key_value":null,"coverage_conditions":"Owner move-in evictions in units covered by the Berkeley Rent Ordinance.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Owner move-in evictions"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Measure BB (Berkeley Rent Ordinance)","quoted_span":"The Rent Board must make inflationary adjustments to owner move-in eviction relocation assistance amounts each year.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D006-01","doc_id":"D006","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Berkeley just cause eviction requirement for covered units","requirement":"A landlord may not evict a tenant in a unit that is fully or partially covered by the Rent Ordinance unless there is just cause.","key_value":null,"coverage_conditions":"Tenants in units that are fully or partially covered by the Berkeley Rent Ordinance.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Fully or partially covered units"},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Measure BB (Berkeley Rent Ordinance)","quoted_span":"In Berkeley, tenants in units that are fully or partially covered by the Rent Ordinance cannot be evicted unless there is \"just cause” (previously called “good cause”).","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
